shell_commands.command:
cd /testbed && patch -p0 <<'PATCH'
--- /dev/null
+++ test/transform/resource/before/UtilityClassGeneric.java
@@ -0,0 +1,19 @@
+import lombok.experimental.UtilityClass;
+
+@UtilityClass
+class UtilityClassGeneric {
+	<T> T convertValue(Class<T> toValueType) {
+		return null;
+	}
+	
+	DTO convert(Object json) {
+		return convertValue(DTO.class);
+	}
+	
+	Object convert(DTO dto) {
+		return null;
+	}
+	
+	class DTO {
+	}
+}
--- /dev/null
+++ test/transform/resource/after-delombok/UtilityClassGeneric.java
@@ -0,0 +1,18 @@
+import lombok.experimental.UtilityClass;
+
+final class UtilityClassGeneric {
+	static <T> T convertValue(Class<T> toValueType) {
+		return null;
+	}
+	static DTO convert(Object json) {
+		return convertValue(DTO.class);
+	}
+	static Object convert(DTO dto) {
+		return null;
+	}
+	static class DTO {
+	}
+	@java.lang.SuppressWarnings("all")
+	private UtilityClassGeneric() {
+		throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
+	}
+}
--- /dev/null
+++ test/transform/resource/after-ecj/UtilityClassGeneric.java
@@ -0,0 +1,21 @@
+import lombok.experimental.UtilityClass;
+final @UtilityClass class UtilityClassGeneric {
+  static class DTO {
+    DTO() {
+      super();
+    }
+  }
+  static <T>T convertValue(Class<T> toValueType) {
+    return null;
+  }
+  static DTO convert(Object json) {
+    return convertValue(DTO.class);
+  }
+  static Object convert(DTO dto) {
+    return null;
+  }
+  private @java.lang.SuppressWarnings("all") UtilityClassGeneric() {
+    super();
+    throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
+  }
+}
PATCH

cd /testbed && patch -p0 <<'PATCH'
--- test/transform/resource/after-delombok/UtilityClassGeneric.java
+++ test/transform/resource/after-delombok/UtilityClassGeneric.java
@@ -16,3 +16,4 @@
 	private UtilityClassGeneric() {
 		throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
 	}
+}
PATCH
ant test.javacCurrent > build/utilityclass-baseline.log 2>&1; code=$?; grep -nE -A12 -B3 'NullPointerException|FAIL|ERROR|UtilityClassGeneric' build/utilityclass-baseline.log | head -100; exit "$code"

cd /testbed && patch -p0 <<'PATCH'
--- src/core/lombok/javac/handlers/HandleUtilityClass.java
+++ src/core/lombok/javac/handlers/HandleUtilityClass.java
@@ -131,6 +131,10 @@
 				if (innerClassSymbol != null && innerClassSymbol.type instanceof ClassType) {
 					((ClassType) innerClassSymbol.type).setEnclosingType(Type.noType);
 				}
+				// The erased type may already have been cached before the class was made static.
+				if (innerClassSymbol != null && innerClassSymbol.erasure_field instanceof ClassType) {
+					((ClassType) innerClassSymbol.erasure_field).setEnclosingType(Type.noType);
+				}
 			}
 		}

--- doc/changelog.markdown
+++ doc/changelog.markdown
@@ -4,1 +4,1 @@
-* No new changes since the release of v1.18.24
+* BUGFIX: `@UtilityClass` no longer causes a javac `NullPointerException` when generic methods and overloaded methods reference an inner class.
PATCH
ant test.compile test.javacCurrent > build/utilityclass-fixed.log 2>&1; code=$?; grep -nE -A12 -B3 '\[ERR\]|\[FAIL\]|UtilityClassGeneric|BUILD (SUCCESSFUL|FAILED)' build/utilityclass-fixed.log; exit "$code"

cd /testbed && patch -p0 <<'PATCH'
--- src/stubs/com/sun/tools/javac/code/Symbol.java
+++ src/stubs/com/sun/tools/javac/code/Symbol.java
@@ -25,3 +25,4 @@
